import{_ as e,o as d,c as a,a2 as r}from"./chunks/framework.BwxVc06z.js";const m=JSON.parse('{"title":"BudgetEngine","description":"","frontmatter":{},"headers":[],"relativePath":"tests/budget_engine.md","filePath":"tests/budget_engine.md"}'),s={name:"tests/budget_engine.md"};function n(i,t,o,h,c,_){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="budgetengine" tabindex="-1">BudgetEngine <a class="header-anchor" href="#budgetengine" aria-label="Permalink to &quot;BudgetEngine&quot;">​</a></h1><p>Phase 3: xi assembled from hardware parameters</p><p><strong>14/14 passed</strong> in 1ms</p><table tabindex="0"><thead><tr><th>Test</th><th>What it does</th><th>Result</th></tr></thead><tbody><tr><td><code>test_budget_inferred</code></td><td>Budget.inferred is infer(T, v_err) where a phase row was formed, T itself where none was, explain&#39;s T_claimed on a run, and a raise on a literature budget.</td><td>✅ pass</td></tr><tr><td><code>test_dac_reaches_link</code></td><td>DAC quantisation noise falls with bit depth, under 1e-3 SNU input-referred at 16 bits, and a q.Link charges budget.dac&#39;s own value.</td><td>✅ pass</td></tr><tr><td><code>test_omitted_hardware</code></td><td>Hardware left None omits its row rather than zeroing it, and assemble() takes no vel, trusted or detector term.</td><td>✅ pass</td></tr><tr><td><code>test_phase_default_form</code></td><td>assemble() emits the estimator form (V_A + xi)*(exp(V_err) - 1) and a plane_note naming Kish, Quantum 8, 1382 (2024), App. E (76)-(82), where it follows from Eqs. (80)-(82) by rearrangement, and Shen, Opt. Express 29, 30978 (2021), Eqs. (18)-(19).</td><td>✅ pass</td></tr><tr><td><code>test_phase_exact</code></td><td>Input-referred, the literature form is exactly 2<em>V_A</em>(1 - exp(-V_err/2)) and ignores T -- Marie &amp; Alleaume, Phys. Rev. A 95, 012316 (2017), Eq. (10).</td><td>✅ pass</td></tr><tr><td><code>test_phase_refuses</code></td><td>Each refusal names its argument: the literature form refuses a channel xi and a transmittance half, and a negative variance or t above 1 is refused.</td><td>✅ pass</td></tr><tr><td><code>test_phase_transmittance</code></td><td>infer() is the transmittance half to phase()&#39;s noise half, t*exp(-v_err) of Kish App. E Eq. (78), and the pair conserves the Bob-plane variance.</td><td>✅ pass</td></tr><tr><td><code>test_plane_rule</code></td><td>Every entry obeys at(&quot;bob&quot;) == T * at(&quot;input&quot;).</td><td>✅ pass</td></tr><tr><td><code>test_raman_convention</code></td><td>Laudenbach Eq. (9.63) is twice Kumar 2015 (impairments.raman) on one density, Kumar keeping the polarising beamsplitter&#39;s half.</td><td>✅ pass</td></tr><tr><td><code>test_raman_density</code></td><td>Laudenbach Eq. (9.63) on a measured dBm/nm density: linear in the density, the filter width and the integration time, zero through a shut filter.</td><td>✅ pass</td></tr><tr><td><code>test_raman_refuses</code></td><td>A negative width or integration time, an infinite density, and a density or a rin with no bandwidth are all refused.</td><td>✅ pass</td></tr><tr><td><code>test_raman_width</code></td><td>The matched filter width is Laudenbach&#39;s 8 pm at 1 GHz on 193.4 THz, and B cancels out of the assembled Raman row.</td><td>✅ pass</td></tr><tr><td><code>test_rin_rows</code></td><td>assemble() emits budget.rin_rows verbatim, values and plane notes alike.</td><td>✅ pass</td></tr><tr><td><code>test_total_ungated</code></td><td>xi_total sums every assembled row, charged or not.</td><td>✅ pass</td></tr></tbody></table>',4)])])}const p=e(s,[["render",n]]);export{m as __pageData,p as default};
